function countType(typ){
  if(!typ||typeof typ!=='string') return {error:'Enter a family, for example CPU.'};
  var t=typ.trim().toUpperCase();
  if(!t) return {error:'Enter a family, for example CPU.'};
  if(TYPES.indexOf(t)===-1) return {error:'Family '+t+' is not one of the sixteen archive families.'};
  var n=0; for(var i=0;i<SAMPLE.length;i++){ if(SAMPLE[i].facet===t) n++; }
  return {type:t, count:n, of:SAMPLE.length};
}
function checkChipId(id){
  if(!id||typeof id!=='string') return {error:'Enter a chip ID, for example JAH-CHIP-000001.'};
  var v=id.trim().toUpperCase();
  if(!v) return {error:'Enter a chip ID, for example JAH-CHIP-000001.'};
  var m=/^JAH-CHIP-(\d{6})$/.exec(v);
  if(!m) return {error:'That is not a chip ID. Chip IDs look like JAH-CHIP-000001.'};
  var n=parseInt(m[1], 10);
  if(n<1||n>35601) return {error:'Chip number '+n+' is outside the archive (1 to 35,601).'};
  return {id:v, number:n, valid:true};
}
function makeFun(seed){
  var r=rng(String(seed==null?'':seed));
  var x=SAMPLE[Math.floor(r()*SAMPLE.length)];
  return 'Fun: Chip counted the pins on "'+x.title+'" and found every single one — twice.';
}
if (typeof module !== 'undefined' && module.exports) module.exports = { countType: countType, checkChipId: checkChipId, makeFun: makeFun };
